function bindMaskControls(){const maskSelect=$('activeMask');maskSelect.onchange=()=>{const [kind,...rest]=maskSelect.value.split(':');changeActiveMask(rest.length?kind:null,rest.join(':'))};$('advanced').addEventListener('toggle',()=>{refreshMaskEditing();scheduleDraw()});$('maskZoom').onchange=e=>{state.maskZoom=Number(e.target.value);refreshMaskEditing();scheduleDraw()};$('addVertex').onclick=()=>{const v=selectedMaskEntry();if(!v){toast(editT().maskNone);return}rememberMask();const pts=v.item.points;let longest=-1,insertAt=0;for(let i=0;i<pts.length;i++){const a=pts[i],b=pts[(i+1)%pts.length],dist=(a[0]-b[0])**2+(a[1]-b[1])**2;if(dist>longest){longest=dist;insertAt=i}}const a=pts[insertAt],b=pts[(insertAt+1)%pts.length];pts.splice(insertAt+1,0,[(a[0]+b[0])/2,(a[1]+b[1])/2]);state.selectedVertex=insertAt+1;renderMaskList();refreshMaskEditing();scheduleDraw()};$('removeVertex').onclick=()=>{const v=selectedMaskEntry();if(!v){toast(editT().maskNone);return}if(state.selectedVertex<0){toast(editT().vertexNone);return}if(v.item.points.length<=3){toast(editT().lastThree);return}rememberMask();v.item.points.splice(state.selectedVertex,1);state.selectedVertex=-1;renderMaskList();refreshMaskEditing();scheduleDraw()};$('undoMask').onclick=()=>{const h=maskHistory.pop();if(!h){toast(editT().nothingUndo);return}let p=profiles[h.profile];p.masks=JSON.parse(h.masks);p.protected=JSON.parse(h.protected);refreshStatus();refreshMaskEditing()};$('resetProfileMasks').onclick=()=>{if(!confirm(editT().confirmReset))return;rememberMask();const p=current(),base=factoryProfiles[state.profileId];p.masks=JSON.parse(JSON.stringify(base.masks));p.protected=JSON.parse(JSON.stringify(base.protected));state.selectedMask=null;state.selectedVertex=-1;refreshStatus();refreshMaskEditing();toast(editT().restored)}}
function pointerStart(e){if(!matched())return;const p=current(),zoom=state.maskZoom;if(state.moveInscription){state.dragInscription={x:e.clientX,y:e.clientY,oldX:state.inscriptionStyle.x,oldY:state.inscriptionStyle.y,rect:canvas.getBoundingClientRect()};canvas.setPointerCapture(e.pointerId);e.preventDefault();return}if(!$('advanced').open)return;
 if(state.drawMode!=='view'){state.draft.push(pointOfEvent(e));scheduleDraw();e.preventDefault();return}
 const [x,y]=pointOfEvent(e);const rect=canvas.getBoundingClientRect(),pxScale=rect.width/p.width,hitLimit=Math.max(16,22/pxScale);let best=hitLimit**2,choice=null;const sel=selectedMaskEntry();let candidates=sel?[sel.item]:[...p.masks,...p.protected];for(const item of candidates)for(let i=0;i<item.points.length;i++){const pt=item.points[i],d=(pt[0]-x)**2+(pt[1]-y)**2;if(d<best){best=d;choice={item,i}}}
 if(!choice&&!sel){for(const item of candidates){if(ctx.isPointInPath(pathFor(item.points),x,y)){changeActiveMask(p.protected.includes(item)?'protected':'masks',item.id);return}}}
 if(choice){if(!sel||sel.item!==choice.item)changeActiveMask(p.protected.includes(choice.item)?'protected':'masks',choice.item.id);rememberMask();state.selectedVertex=choice.i;state.editing={a:choice.item,i:choice.i};canvas.setPointerCapture(e.pointerId);renderMaskList();refreshMaskEditing();scheduleDraw();e.preventDefault()}}
function pointerUpdate(e){if(state.dragInscription){const a=state.dragInscription,rate=current().width/a.rect.width;state.inscriptionStyle.x=Math.round(Math.max(-220,Math.min(220,a.oldX+(e.clientX-a.x)*rate)));state.inscriptionStyle.y=Math.round(Math.max(-55,Math.min(55,a.oldY+(e.clientY-a.y)*rate)));inscriptionFormSync();scheduleDraw();e.preventDefault();return}if(state.editing){state.editing.a.points[state.editing.i]=pointOfEvent(e).map(Math.round);scheduleDraw();e.preventDefault()}}
function pointerEnd(){if(state.dragInscription){saveInscriptionPrefs();state.dragInscription=null}if(state.editing){state.editing=null;invalidateLightMap();renderMaskList();refreshMaskEditing();scheduleDraw()}}

function bindEvents(){$('lightMapToggle').onclick=()=>{state.showLightMap=!state.showLightMap;updateLightMapCopy();scheduleDraw()};$('lightMapExport').onclick=()=>{const field=getLightMap(),p=current();if(!field||!p){toast(tr().photoNone);return}const out=document.createElement('canvas');out.width=p.width;out.height=p.height;out.getContext('2d').drawImage(field,0,0,p.width,p.height);pngDownload(out.toDataURL('image/png'),`synagogue_lighting_${p.id}.png`)};document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
$('maskProfile').addEventListener('change',e=>changeProfile(e.target.value));
$('photoFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(f)await loadLocalFile(f);e.target.value=''});
$('uploadBtn').onclick=$('emptyUpload').onclick=()=>$('photoFile').click();$('useDemo').onclick=async()=>{let p=current();if(!p.demo)return;const img=await imageLoad(p.demo);setPhotoForProfile(p.id,img,'demo','clean-master example')};
for(const [id,key] of [['opacity','opacity'],['lighting','lighting'],['scale','scale']])$(id).addEventListener('input',e=>{state[key]=Number(e.target.value);$(id+'Value').textContent=state[key].toFixed(2);scheduleDraw()});
$('protectObjects').onchange=e=>{state.protect=e.target.checked;scheduleDraw()};$('showMasks').onchange=e=>{state.showMasks=e.target.checked;scheduleDraw()};$('inscriptionEnabled').onchange=e=>{state.inscriptionEnabled=e.target.checked;saveInscriptionPrefs();scheduleDraw()};bindInscriptionControls();bindMaskControls();
$('compareBtn').addEventListener('pointerdown',()=>{state.compare=true;scheduleDraw()});for(const ev of ['pointerup','pointerleave','pointercancel'])$('compareBtn').addEventListener(ev,()=>{state.compare=false;scheduleDraw()});$('compareBtn').onkeydown=e=>{if(e.key===' '||e.key==='Enter'){state.compare=true;scheduleDraw()}};$('compareBtn').onkeyup=()=>{state.compare=false;scheduleDraw()};
$('exportBtn').onclick=()=>{if(!matched()){toast(tr().chooseFirst);return}let old=state.compare,oldMasks=state.showMasks,oldMode=state.drawMode;state.compare=false;state.showMasks=false;state.drawMode='view';renderNow();try{pngDownload(canvas.toDataURL('image/png'),`synagogue_${state.profileId}_${state.scenario}.png`);toast(tr().saveOK)}catch(e){toast(e.message)}state.compare=old;state.showMasks=oldMasks;state.drawMode=oldMode;scheduleDraw()};
$('drawMode').onchange=e=>{state.drawMode=e.target.value;state.moveInscription=false;inscriptionFormSync();state.draft=[];if(state.drawMode!=='view'){$('showMasks').checked=true;state.showMasks=true}scheduleDraw()};
$('finishPolygon').onclick=()=>{if(state.draft.length<3){toast(tr().polygon3);return}let p=current(),type=state.drawMode;if(type==='view')return;let item={id:'USER_'+Date.now(),points:state.draft.map(([x,y])=>[Math.round(x),Math.round(y)])};if(type==='protect')p.protected.push(item);else p.masks.push({...item,group:type});state.draft=[];refreshStatus();refreshMaskEditing()};$('cancelPolygon').onclick=()=>{state.draft=[];scheduleDraw()};
canvas.addEventListener('pointerdown',pointerStart);
canvas.addEventListener('pointermove',pointerUpdate);
for(const eventName of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(eventName,pointerEnd);
$('saveProject').onclick=()=>{const payload={type:'synagogue-material-studio',version:'1.2',inscription:{enabled:state.inscriptionEnabled,style:state.inscriptionStyle},profileId:state.profileId,profiles:Object.fromEntries(Object.entries(profiles).map(([id,p])=>[id,{width:p.width,height:p.height,masks:p.masks,protected:p.protected}])),scenario:state.scenario,materials:state.materials};blobDownload(JSON.stringify(payload,null,2),'synagogue_mask_project.json','application/json');toast(tr().saveOK)};
$('loadProject').onclick=()=>$('projectFile').click();$('projectFile').onchange=async e=>{let file=e.target.files?.[0];if(!file)return;try{let data=JSON.parse(await file.text());if(data.type!=='synagogue-material-studio'||!data.profiles)throw Error('Bad JSON');for(const [id,u] of Object.entries(data.profiles)){if(!profiles[id]||u.width!==profiles[id].width||u.height!==profiles[id].height||!Array.isArray(u.masks)||!Array.isArray(u.protected))continue;let valid=arr=>arr.every(item=>Array.isArray(item.points)&&item.points.length>=3&&item.points.every(pt=>Array.isArray(pt)&&pt.length===2&&pt.every(Number.isFinite)));if(!valid(u.masks)||!valid(u.protected))continue;profiles[id].masks=structuredClone(u.masks);profiles[id].protected=structuredClone(u.protected);invalidateLightMap(id)}if(data.materials)for(let k of ZONES)if(catalog.some(x=>x.id===data.materials[k]))state.materials[k]=data.materials[k];if(SCENARIOS.includes(data.scenario))state.scenario=data.scenario;if(data.inscription?.style){state.inscriptionEnabled=Boolean(data.inscription.enabled);for(const [k,v] of Object.entries(data.inscription.style))if(Object.prototype.hasOwnProperty.call(DEFAULT_INSCRIPTION,k)&&typeof v===typeof DEFAULT_INSCRIPTION[k])state.inscriptionStyle[k]=v;saveInscriptionPrefs();inscriptionFormSync()}renderControls();await changeProfile(profiles[data.profileId]?data.profileId:state.profileId);toast(tr().importOK)}catch(err){toast(tr().badFile)}e.target.value=''};
}
async function boot(){try{const [maskData,products]=window.SMS_DATA ? [window.SMS_DATA.maskData,window.SMS_DATA.catalog] : await Promise.all([fetchJSON('./masks.json'),fetchJSON('./catalog.json')]);profiles=maskData.profiles;factoryProfiles=JSON.parse(JSON.stringify(profiles));catalog=products;const textureResults=await Promise.all(catalog.map(async m=>{try{return [m.id,await imageLoad(m.texturePath)]}catch(e){return [m.id,null]}}));tiles=Object.fromEntries(textureResults);
bindEvents();for(const key of ['addVertex','removeVertex','undoMask','resetProfileMasks','finishPolygon'])$(key).addEventListener('click',()=>{invalidateLightMap();scheduleDraw()});for(const key of ['opacity','lighting','scale'])$(key+'Value').textContent=state[key].toFixed(2);let language='he';try{language=localStorage.getItem('sms-v1-language')||'he'}catch(e){}setLanguage(language);restoreInscriptionPrefs();inscriptionFormSync();db=await openDatabase();await changeProfile(maskData.default);ready=true;
// Try supplier previews without blocking initial rendering. Manufacturer imagery may be blocked by CORS.
for(const m of catalog)probeOfficial(m);
}catch(err){console.error(err);warn('Startup error / שגיאת הפעלה: '+err.message)}}
boot();
